def P(text, style='BodyX'):
    return Paragraph(text, styles[style])

def bullet(items):
    return [P('&bull; ' + x) for x in items]

def table(rows, widths=None, header=True, font=8.1):
    cooked = [[P(str(x), 'SmallX' if not (header and i == 0) else 'CardTitle') for x in row] for i, row in enumerate(rows)]
    t = Table(cooked, colWidths=widths, repeatRows=1 if header else 0, hAlign='LEFT')
    ts = [('VALIGN',(0,0),(-1,-1),'TOP'), ('GRID',(0,0),(-1,-1),0.35,LINE), ('LEFTPADDING',(0,0),(-1,-1),6), ('RIGHTPADDING',(0,0),(-1,-1),6), ('TOPPADDING',(0,0),(-1,-1),5), ('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if header: ts += [('BACKGROUND',(0,0),(-1,0),PALE), ('TEXTCOLOR',(0,0),(-1,0),NAVY)]
    else: ts += [('BACKGROUND',(0,0),(-1,-1),colors.white)]
    t.setStyle(TableStyle(ts))
    return t

def callout(title, body, bg=GREEN):
    t = Table([[P(title, 'CardTitle'), P(body, 'SmallX')]], colWidths=[3.4*cm, 12.7*cm])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),bg),('BOX',(0,0),(-1,-1),0.5,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
    return t

def footer(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(LINE); canvas.line(doc.leftMargin, 1.2*cm, A4[0]-doc.rightMargin, 1.2*cm)
    canvas.setFont('Helvetica', 8); canvas.setFillColor(MUTED)
    canvas.drawString(doc.leftMargin, .78*cm, 'Instagram Analytics Project Guide')
    canvas.drawRightString(A4[0]-doc.rightMargin, .78*cm, f'Page {doc.page}')
    canvas.restoreState()

