story.append(Table([[P('<b>Project purpose</b><br/>Turn Instagram-style activity data into meaningful user engagement features, then use machine learning to classify engagement-based influencer status and estimate engagement per post.', 'BodyX'), P('<b>What this guide covers</b><br/>Project story, data tables, end-to-end workflow, feature engineering, models, evaluation, limitations, interview answers, and self-introduction script.', 'BodyX')]], colWidths=[8.1*cm,8.1*cm], style=[('BACKGROUND',(0,0),(-1,-1),PALE),('BOX',(0,0),(-1,-1),0.7,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),12)]))
story += [Spacer(1,.7*cm), P('Project at a glance', 'H1X'), table([['Area','Implemented in this project'],['Data source','Seven CSV files representing users, posts, likes, comments, follows, photo tags, and tags.'],['Classification task','Predict “Influencer” vs “Not Influencer” from a user’s total likes and comments.'],['Regression tasks','Predict likes per post and comments per post from follower and post counts.'],['Models','RandomForestClassifier and two RandomForestRegressor models.'],['Analytics','Confusion matrix plus followers-vs-likes and posts-vs-engagement scatter plots.']], [3.4*cm,12.8*cm]), Spacer(1,.4*cm), callout('Best one-line summary', 'I built an Instagram analytics project that combines relational social-media data, engineers engagement features, and applies random forest models for engagement-based classification and per-post engagement forecasting.')]
