story += [P('1. Project Story and Business Problem','H1X'), P('Social-media platforms generate many connected events: users publish photos, other users like or comment on them, and users follow one another. Looking at a single table does not show who is engaging, whose content receives engagement, or what level of response a new account may get. This project joins those events into user-level features and turns them into simple predictive tasks.'), P('The project answers two practical questions:', 'H2X')] + bullet(['<b>Classification:</b> Based on a user’s activity (likes and comments made), does the project place that user above the median engagement threshold?', '<b>Forecasting:</b> Given an account’s follower count and number of posts, what likes per post and comments per post can be expected?'])
story += [P('End-to-end workflow','H1X')]
