story += [P('2. Dataset and Data Model','H1X'), P('The project uses a normalized Instagram-like relational dataset. The recorded dataset contains 100 users, 257 photos, 1,000 likes, 1,000 comments, 1,000 follow relationships, 501 photo-tag links, and 21 tags.'), table([['File','Rows','Important fields','How it is used'],['users.csv','100','id, username, created_at','Base user table for both modelling pipelines.'],['photos.csv','257','id, user_id, image_url, created_dat','Counts posts and maps reactions back to content creators.'],['likes.csv','1,000','user_id, photo_id, created_at','Counts actions by users; also joins through photo to count likes received.'],['comments.csv','1,000','id, comment_text, user_id, photo_id, created_at','Counts actions by users; also joins through photo to count comments received.'],['follows.csv','1,000','follower_id, followee_id, created_at','Counts followers for each followee.'],['photo_tags.csv','501','photo_id, tag_id','Available in the data but not used in the current models.'],['tags.csv','21','id, tag_name, created_at','Available for hashtag/tag analysis; not used in the current models.']], [2.3*cm,1.05*cm,5.1*cm,7.75*cm]), P('Relationship map','H2X'), P('<b>users.id</b> links to photos.user_id (creator), likes.user_id (liker), comments.user_id (commenter), follows.follower_id, and follows.followee_id. <b>photos.id</b> links to likes.photo_id, comments.photo_id, and photo_tags.photo_id. <b>tags.id</b> links to photo_tags.tag_id.','BodyX'), callout('Important terminology','The notebook uses “likes/comments by a user” for the classifier, but “likes/comments received on a user’s photos” for the regression pipeline. This difference is intentional in the code and should be explained clearly.', AMBER)]
