story += [P('3. Module A - Influencer Classification','H1X'), P('This module is an engagement-threshold classifier. It first makes a user-level table from <b>users</b>, then counts each user’s records in likes and comments. Missing counts become zero.'), P('Feature engineering and label','H2X'), table([['Item','Definition in the notebook','Why it matters'],['total_likes','Number of like records where the user is the liker.','Measures a user’s liking activity.'],['total_comments','Number of comment records where the user is the commenter.','Measures a user’s commenting activity.'],['engagement','total_likes + total_comments','Combined activity score.'],['influencer (target)','1 when engagement > median engagement; otherwise 0.','Creates a balanced-ish binary label from the project dataset.']], [3.2*cm,7.0*cm,6.0*cm]), P('Baseline before machine learning','H2X'), P('The notebook includes a simple rule-based prediction: receive likes and comments as input, add them, and compare the total with the dataset median engagement. Above the median gives “Influencer”; otherwise “Not Influencer.” This provides a transparent baseline.'), P('ML pipeline','H2X')] + bullet(['Inputs X: <b>total_likes</b> and <b>total_comments</b>. Target y: <b>influencer</b>.', 'Training/testing: <b>train_test_split</b> with test_size=0.20 and random_state=42.', 'Algorithm: <b>RandomForestClassifier()</b>. A random forest aggregates decisions from multiple decision trees.', 'Output: binary prediction, then the notebook prints accuracy and a classification report.'])
story += [callout('Recorded evaluation result','The saved notebook output reports accuracy = <b>1.00</b> on 20 test users. For class 0, precision/recall/F1 are all 1.00 (support 12); for class 1, all are 1.00 (support 8).', GREEN), Spacer(1,.15*cm), P('Why this result must be interpreted carefully','H2X'), P('The target is calculated directly from the same two input features: engagement = total_likes + total_comments, then influencer is whether engagement is above its median. This makes the classification task close to learning a known threshold from its own ingredients. The 100% score confirms the code pipeline on this split; it does <b>not</b> demonstrate reliable real-world influencer prediction. A production label should come from an independent business definition, such as verified status, campaign performance, or a future engagement outcome.','BodyX')]
