story += [P('4. Module B - Per-Post Engagement Forecasting','H1X'), P('This module changes perspective from user actions to content-creator outcomes. Likes and comments are joined to photos by photo_id, then grouped by the photo owner. This produces engagement received by each creator.'), P('Data preparation','H2X')] + bullet(['Count followers by grouping follows on <b>followee_id</b>.', 'Count posts by grouping photos on <b>user_id</b>.', 'Join likes and comments to photos; group by the photo owner to count likes and comments received.', 'Left-merge all aggregates onto users and fill missing values with zero.', 'Create rate targets: <b>likes_per_post = likes / (posts + 1)</b> and <b>comments_per_post = comments / (posts + 1)</b>. The +1 prevents division by zero.', 'Remove very high values using the 99th percentile rule independently for likes_per_post and comments_per_post.'])
