story += [P('7. Limitations, Improvements, and Honest Project Positioning','H1X'), P('A strong project explanation includes both what works and what you would improve. This project is a well-structured learning pipeline for social-media data aggregation and random forests, but it is not yet a production influencer scoring system.'), table([['Current limitation','Why it matters','Practical improvement'],['Derived target leakage in classification','The target is a threshold of the same likes/comments supplied as features; high performance is expected.','Use an independent label or predict future-period engagement from past-period features.'],['Small dataset','100 users makes a single 80/20 split unstable and limits generalization.','Collect more accounts; use stratified cross-validation and a holdout set.'],['No regression metrics','Forecast quality cannot be quantified.','Report MAE, RMSE, R2, and a baseline comparison for each target.'],['Limited inputs','Only followers and posts feed the regressors.','Add account age, posting frequency, recency, tags, content category, time, and prior engagement.'],['Outlier removal rule','The 99th-percentile filter may remove useful high-performing accounts.','Document retained rows, compare robust alternatives, and fit transformations.'],['Hard-coded output floors','min 50 likes / 2 comments can hide a low model forecast.','Show raw prediction and label any business rule separately.'],['Reproducibility','Random forest objects have no random_state in the notebook.','Set random_state=42 and record package versions.']], [3.3*cm,6.1*cm,6.8*cm]), P('Recommended next iteration','H2X'), P('Build a time-aware dataset: use engagement from a past window to predict engagement in a future window. Add tags and photo-level features, use cross-validation, compare random forest against a simple baseline, calculate regression metrics, and present results in a lightweight Streamlit dashboard.','BodyX')]
